<?php $catalog=$service::catalog();$values=$editing['fields']??[]; ?>
<header class="page-header"><div><h1><?= e(t($workspaceTitle)) ?></h1><p class="muted"><?= e(t($description)) ?></p></div><a href="<?= e($base) ?>/report"><?= e(t('Printable report')) ?></a></header><?php require ROOT.'/app/Core/views/notices.php'; ?>
<nav class="tabs" aria-label="<?= e(t('Workspace tools')) ?>"><?php foreach($catalog as $key=>[$label]): ?><a href="<?= e($base) ?>?page=<?= e($key) ?>" <?= $key===$kind?'aria-current="page"':'' ?>><?= e(t($label)) ?></a><?php endforeach; ?></nav>
<?php if(isset($summaryView))require $summaryView; ?>
<section class="card"><h2><?= $editing?t('Edit'):t('Add') ?> <?= e(t($catalog[$kind][0])) ?></h2><form class="form-grid" method="post" action="<?= e($base) ?>/<?= e($kind) ?>/save"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($editing['id']??'') ?>">
<?php foreach($catalog[$kind][1]as $field=>$definition):$optional=str_starts_with($definition,'?');$type=ltrim($definition,'?');$value=$values[$field]??($type==='date'?ui_date('Y-m-d'):'');$options=$service::options($type); ?><label><?= e(t(ucfirst(str_replace('_',' ',$field)))) ?><?= $optional?' (optional)':'' ?>
<?php if(str_starts_with($type,'ref:')):$references=$service::rows(substr($type,4)); ?><select name="<?= e($field) ?>" <?= $optional?'':'required' ?>><option value=""><?= e(t('Choose…')) ?></option><?php foreach($references as $reference): ?><option value="<?= e($reference['id']) ?>" <?= (string)$value===(string)$reference['id']?'selected':'' ?>><?= e($reference['fields']['title']??$reference['fields']['name']??reset($reference['fields'])) ?></option><?php endforeach; ?></select>
<?php elseif(in_array($field,['module_id','assignment_id','exam_id','work_project_id'],true)):$table=match($field){'module_id'=>'uni_modules','assignment_id'=>'assignments','exam_id'=>'exams','work_project_id'=>'work_projects'};$refs=Db::all('SELECT * FROM '.$table.' ORDER BY id DESC'); ?><select name="<?= e($field) ?>" <?= $optional?'':'required' ?>><option value=""><?= e(t('Choose…')) ?></option><?php foreach($refs as $ref): ?><option value="<?= e($ref['id']) ?>" <?= (string)$value===(string)$ref['id']?'selected':'' ?>><?= e($ref['title']??$ref['name']??$ref['identifier']??('Record '.$ref['id'])) ?></option><?php endforeach; ?></select>
<?php elseif($options): ?><select name="<?= e($field) ?>"><?php foreach($options as $v=>$label): ?><option value="<?= e($v) ?>" <?= (string)$value===(string)$v?'selected':'' ?>><?= e(t(ucfirst(str_replace('_',' ',$label)))) ?></option><?php endforeach; ?></select>
<?php elseif(in_array($field,['notes','markdown','topics','mistake','correction','criteria','requirements','summary','outcome','description'],true)): ?><textarea name="<?= e($field) ?>" rows="4" maxlength="20000" <?= $optional?'':'required' ?>><?= e($value) ?></textarea>
<?php else:$htmlType=match(true){in_array($type,['date','time','month'],true)=>$type,$type==='url'=>'url',str_starts_with($type,'int:')||in_array($type,['money','money0','decimal'],true)=>'number',default=>'text'};$attrs='';if(str_starts_with($type,'int:')){[,$min,$max]=explode(':',$type);$attrs='min="'.$min.'" max="'.$max.'" step="1"';}elseif(in_array($type,['money','money0','decimal'],true))$attrs='min="'.($type==='money'?'0.01':'0').'" step="'.($type==='decimal'?'0.0001':'0.01').'"'; ?><input type="<?= e($htmlType) ?>" name="<?= e($field) ?>" value="<?= e($value) ?>" maxlength="20000" <?= $attrs ?> <?= $optional?'':'required' ?>><?php endif; ?></label><?php endforeach; ?><div class="full"><button><?= e(t('Save')) ?></button> <a href="<?= e($base) ?>?page=<?= e($kind) ?>"><?= e(t('Cancel edit')) ?></a></div></form></section>
<section class="card"><form class="inline" method="get" action="<?= e($base) ?>"><input type="hidden" name="page" value="<?= e($kind) ?>"><label><?= e(t('Search saved records')) ?><input name="q" maxlength="200" value="<?= e($search) ?>"></label><button class="secondary"><?= e(t('Search')) ?></button></form><h2><?= e(t($catalog[$kind][0])) ?></h2><?php if(!$rows): ?><p class="muted"><?= e(t('No matching records yet.')) ?></p><?php endif; ?>
<?php foreach($rows as $record):$d=$record['fields']; ?><article class="lesson-entry"><h3><?= e($d['title']??$d['name']??$d['company']??$d['book']??$d['description']??$catalog[$kind][0]) ?></h3><dl><?php foreach($catalog[$kind][1]as $field=>$definition):$type=ltrim($definition,'?');$display=$d[$field]??'';if($display!==''&&str_starts_with($type,'ref:')){$related=$service::get((int)$display,substr($type,4));$display=$related['fields']['title']??$related['fields']['name']??reset($related['fields']);} ?><dt><?= e(t(ucfirst(str_replace('_',' ',$field)))) ?></dt><dd><?= nl2br(e($display)) ?></dd><?php endforeach; ?></dl><?php if(isset($detailView))require $detailView; ?><div class="inline"><a href="<?= e($base) ?>?page=<?= e($kind) ?>&amp;edit=<?= e($record['id']) ?>"><?= e(t('Edit')) ?></a><form method="post" action="<?= e($base) ?>/<?= e($kind) ?>/<?= e($record['id']) ?>/archive" data-confirm="Archive this record? Linked records must be resolved first."><?= csrf_field() ?><button class="quiet"><?= e(t('Archive')) ?></button></form></div></article><?php endforeach; ?></section>
